You are an expert Unity engineer. Below is a small Unity scenario. Predict, exactly, the trace it produces when it is run in real Unity.

How the scenario is executed (Unity 6000.3.2f1, Mono scripting backend, Editor play mode, empty scene, default project settings except where Run() changes them):
- Time.captureFramerate = 50, so every frame advances exactly 0.02 s of game time; Time.fixedDeltaTime = 0.02; Time.timeScale = 1; Physics.gravity is the default unless Run() changes it.
- Scenario.Run() is called once, at the very start of the first player-loop iteration, before any Unity callback of frame 1. It is not a MonoBehaviour. Anything it logs (including callbacks triggered synchronously from inside it, such as Awake and OnEnable of a freshly added component) comes first, before the `--- frame 1 ---` line.
- The harness itself writes the line `--- frame N ---` at the very start of every player-loop iteration (N = 1, 2, ...), before Unity runs any callback of that frame.
- The trace covers frames 1 to Scenario.Frames inclusive and then stops. Nothing runs after that.
- Every Trace.Log call appends one line. If Unity logs an unhandled exception, the harness appends `EXCEPTION: <ExceptionTypeName>` (type name only) at that point in the trace.
- Nothing else is logged. Not shown: the Unity version's own warnings. Assume no other scripts exist.

Answer format: think as long as you need, then give the complete trace in one fenced code block, one line per trace line, in order, including the `--- frame N ---` lines. Do not add commentary inside the block.

// ---- Common.cs ----
using System.Collections.Generic;
using UnityEngine;

// Shared by every scenario. Trace.Log appends one line to the trace. The harness
// also writes "--- frame N ---" at the very start of every player-loop iteration.
public static class Trace
{
    public static readonly List<string> Lines = new List<string>();
    // Rounds to 2 decimals and prints without trailing zeros; negative zero prints as 0.
    public static string R(float x) => (Mathf.Round(x * 100f) / 100f + 0f).ToString("0.##", System.Globalization.CultureInfo.InvariantCulture);
    public static string V(Vector3 v) => $"({R(v.x)}, {R(v.y)}, {R(v.z)})";
    public static void Log(string message) => Lines.Add(message);
}

// Logs every lifecycle callback it receives as "<gameObject.name>:<Callback>".
// Update/FixedUpdate/LateUpdate only log while logTicks is true.
public class Probe : MonoBehaviour
{
    public bool logTicks;
    void Awake() => Trace.Log($"{name}:Awake");
    void OnEnable() => Trace.Log($"{name}:OnEnable");
    void Start() => Trace.Log($"{name}:Start");
    void FixedUpdate() { if (logTicks) Trace.Log($"{name}:FixedUpdate"); }
    void Update() { if (logTicks) Trace.Log($"{name}:Update"); }
    void LateUpdate() { if (logTicks) Trace.Log($"{name}:LateUpdate"); }
    void OnDisable() => Trace.Log($"{name}:OnDisable");
    void OnDestroy() => Trace.Log($"{name}:OnDestroy");
}

// ---- S01_activation.cs ----
using UnityEngine;

namespace S01
{
    public static class Scenario
    {
        public const int Frames = 3;

        public static void Run()
        {
            var a = new GameObject("A");
            a.AddComponent<Probe>();

            var b = new GameObject("B");
            b.SetActive(false);
            b.AddComponent<Probe>();

            var c = new GameObject("C");
            c.transform.SetParent(b.transform);
            c.AddComponent<Probe>();

            Trace.Log("activating B");
            b.SetActive(true);
            Trace.Log("Run done");
        }
    }
}

