using UnityEngine;

namespace S29
{
    public class Reaper : MonoBehaviour
    {
        public GameObject root, a, b, a1;
        int n;
        void Update()
        {
            n++;
            if (n != 1) return;
            a1.transform.SetParent(null);
            Trace.Log("detached A1");
            Destroy(a);
            Destroy(root);
            Destroy(root);
            Trace.Log($"count now {FindObjectsByType<Probe>(FindObjectsSortMode.None).Length}");
